/*master.mdam.selectMasterMdAmProxyMainWorkProcessAuthGbn*/
/* SLOGIC-BEGIN (P07-0000018) */
SELECT 
	CASE
		WHEN COL01_DATA LIKE '%'||#{user_id}||'%' THEN 'DL'
		WHEN COL02_DATA LIKE '%'||#{user_id}||'%' THEN 'TL'
		WHEN COL03_DATA LIKE '%'||#{user_id}||'%' THEN 'BL'
		ELSE 'MB' END AS AUTH_GBN
FROM BNTSLGIMP
WHERE 
		SLG_ID = 'P07-0000018'
	AND COM_CODE = #{com_code}
/* SLOGIC-END */

/*master.mdam.selectMasterMdAmProxyMainWorkProcessList*/ SELECT DISTINCT(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER) AS BUYER_NAME_LOC -- 0 구매사 , NVL(B.IV_DO_NO_CNT,0) AS IV_DO_NO_CNT -- 1 수주접수_미접수건 , NVL(B.IV_LONG_DO_NO_CNT,0) AS IV_LONG_DO_NO_CNT -- 2 수주접수_장기미접수건 , NVL(B.IV_EXPECT_DELAY_CNT,0) AS IV_EXPECT_DELAY_CNT -- 3 납기_지연예상건 , NVL(B.IV_DELAY_CNT,0) AS IV_DELAY_CNT -- 4 납기_지연건 , NVL(B.IV_LONG_EXPECT_DELAY_CNT,0) AS IV_LONG_EXPECT_DELAY_CNT -- 5 납기_장기지연건 , NVL(B.IV_DI_NO_CNT,0) AS IV_DI_NO_CNT -- 6 납기_실적미등록건 , NVL((SELECT SUM(QT_RECV_CNT) FROM KEP_PM_PA_MNG WHERE BUYER = B.BUYER),0) AS QT_RECV_CNT -- 7 견적_의뢰건 --KEPRQDT.ITEM_GROUP = NULL 이면 취합시 'M'으로 카운트, (OPA팀 확인불가), 해서 M+O한 수량을 사업팀 OPA팀 표시. , NVL(B.QT_DELAY_CNT,0) AS QT_DELAY_CNT -- 8 견적_제출지연건 , NVL(B.QT_LONG_DELAY_CNT,0) AS QT_LONG_DELAY_CNT -- 9 견적_장기지연건 , A.BUYER AS BUYER -- 10 , NVL(B.IV_BAD_DELAY_CNT,0) AS IV_BAD_DELAY_CNT -- 11 납기_악성지연건 , ( SELECT COUNT(*) FROM IF_PROGRESS C WHERE C.BUYER =A.BUYER AND C.IF_FLAG IN ('A','N') AND C.GUBUN = 'PO') AS IF_ERR_CNT -- 12 I/F오류 , ( SELECT COUNT(DISTINCT X.PR_NO||Y.LEGACY_PO_NO||X.BUYER) FROM ICOMPRHD X, ICOMPRDT Y WHERE X.RECV_FLAG = 'AT' AND X.PR_NO = Y.PR_NO AND X.BUYER = Y.BUYER AND X.BUYER = A.BUYER AND X.SAVE_FLAG = 'PX' AND X.STATUS != 'D' AND Y.STATUS != 'D') AS IF_STOP_CNT -- I/F 임시저장 , ( SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID=A.KEP_USER_ID) AS KEP_USER_NAME -- 13 , NVL(B.GR_NO_CNT,0) AS GR_NO_CNT -- 14 납기_미입고건 , A.ITEM_GROUP AS ITEM_GROUP , NVL(B.NW_ITM_SPEC_REQ_CNT,0) AS NW_ITM_SPEC_REQ_CNT -- 신규상품규격의뢰 , NVL(B.NW_ITM_SPEC_CHK_CNT,0) AS NW_ITM_SPEC_CHK_CNT -- 신규상품규격의뢰확인 , NVL(B.QT_NEGO_REQ_CNT,0) AS QT_NEGO_REQ_CNT -- Nego의뢰건 , TO_CHAR(B.PROC_DTTM,'YYYYMMDD') AS PROC_DT -- 집계 처리날짜 , TO_CHAR(B.PROC_DTTM,'HH24:MI') AS PROC_TM -- 집계 처리시간 FROM MIS_BUYER_MNG A, KEP_PM_PA_MNG B WHERE A.YEAR=TO_CHAR(SYSDATE, 'YYYY')
AND A.BUYER = #{buyer}
AND A.KEP_USER_ID = #{user_id} AND A.STATUS ='C' AND B.ITEM_GROUP (+)= 'M' AND A.BUYER=B.BUYER(+) ORDER BY 1
